INSERT IGNORE INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `meta_title`, `meta_description`, `keywords`, `author_id`, `category`, `is_published`, `published_at`, `created_at`, `updated_at`) VALUES ('Liverpool\'s problems last season were not really tactical. They were about trust', ' accountability', ' and a collective sense of purpose. Andoni Iraola', ' more than almost anyone else', ' is exactly the kind of manager who can rebuild all three.,data:image/jpeg;base64', ',Andoni Iraola at Liverpool: The Right Man for a Club That Needs More Than a Manager,Andoni Iraola at Liverpool: The Right Man for a Club That Needs More Than a Manager,Andoni Iraola', ' Liverpool Right Man', ' for', ' a', ' Club', ' That', ' Needs', ' More', ' Than', ' a');
